        String emailId = RandomString.make() + "@baeldung.com";
        String password = RandomString.make();
        String requestBody = String.format("{\n    \"emailId\"  : \"%s\",\n    \"password\" : \"%s\"\n}\n", emailId, password);
        String url = "/users";

        mockMvc.perform(post(url).contentType(APPLICATION_JSON)
            .content(requestBody))
            .andExpect(status().isOk());
    }

